# O(n): yon sèl bouk
def chèche(lis, sib):
    for x in lis:        # n etap maksimòm
        if x == sib:
            return True
    return False

# O(n²): bouk anndan bouk - evite si posib!
for a in lis:
    for b in lis:        # n × n etap
        konpare(a, b)

