def kalkile_total(pri, kantite, rabè=0):
    return pri * kantite * (1 - rabè)

def test_total_senp():
    assert kalkile_total(100, 2) == 200

def test_total_rabè():
    assert kalkile_total(100, 2, 0.1) == 180

def test_total_zero():
    assert kalkile_total(100, 0) == 0   # ka limit!
